namespace UniversityCourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public string ImageUrl { get; set; } = string.Empty;
}

namespace UniversityCourseCatalog.Models;

public class Course
{
    public int Id { get; set; }
    public int DepartmentId { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;
    public string InstructorName { get; set; } = string.Empty;
    public string InstructorBio { get; set; } = string.Empty;
    public bool IsFeatured { get; set; }
}

using System.ComponentModel.DataAnnotations;

namespace UniversityCourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Student name is required.")]
    public string Name { get; set; } = string.Empty;

    [Required(ErrorMessage = "Student ID is required.")]
    public string StudentId { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please select a course.")]
    [Range(1, int.MaxValue, ErrorMessage = "Please select a course.")]
    public int CourseId { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public interface ICatalogService
{
    List<Department> GetDepartments();
    Department? GetDepartment(int id);
    List<Course> GetCourses(string? search, int? departmentId);
    Course? GetCourse(int id);
    List<Course> GetFeaturedCourses();
    bool SubmitEnrollmentRequest(EnrollmentRequest request);
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService : ICatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Name = "Computer Science", Description = "Study of computation, algorithms, and information systems.", ImageUrl = "" },
            new() { Id = 2, Name = "Mathematics", Description = "Explore abstract structures, patterns, and quantitative reasoning.", ImageUrl = "" },
            new() { Id = 3, Name = "Physics", Description = "Understand the fundamental laws governing the universe.", ImageUrl = "" },
            new() { Id = 4, Name = "English", Description = "Develop skills in writing, literature, and critical analysis.", ImageUrl = "" }
        };

        _courses = new List<Course>
        {
            // Computer Science
            new() { Id = 1, DepartmentId = 1, Title = "Introduction to Programming", Description = "Learn the fundamentals of programming using C#.", Credits = 3, Schedule = "Mon/Wed 9:00-10:15 AM", InstructorName = "Dr. Alice Chen", InstructorBio = "PhD in Computer Science from MIT with 15 years of teaching experience.", IsFeatured = true },
            new() { Id = 2, DepartmentId = 1, Title = "Data Structures and Algorithms", Description = "Study fundamental data structures and algorithm design techniques.", Credits = 4, Schedule = "Tue/Thu 11:00 AM-12:15 PM", InstructorName = "Dr. Bob Martinez", InstructorBio = "Former software engineer at Google, specializing in algorithm optimization.", IsFeatured = false },
            new() { Id = 3, DepartmentId = 1, Title = "Web Development", Description = "Build modern web applications using ASP.NET Core and Blazor.", Credits = 3, Schedule = "Mon/Wed/Fri 1:00-1:50 PM", InstructorName = "Dr. Alice Chen", InstructorBio = "PhD in Computer Science from MIT with 15 years of teaching experience.", IsFeatured = true },
            // Mathematics
            new() { Id = 4, DepartmentId = 2, Title = "Calculus I", Description = "Limits, derivatives, and integrals of single-variable functions.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00-10:50 AM", InstructorName = "Dr. Carol Singh", InstructorBio = "Published researcher in applied mathematics and differential equations.", IsFeatured = true },
            new() { Id = 5, DepartmentId = 2, Title = "Linear Algebra", Description = "Vector spaces, matrices, and linear transformations.", Credits = 3, Schedule = "Tue/Thu 2:00-3:15 PM", InstructorName = "Dr. Carol Singh", InstructorBio = "Published researcher in applied mathematics and differential equations.", IsFeatured = false },
            new() { Id = 6, DepartmentId = 2, Title = "Discrete Mathematics", Description = "Logic, sets, combinatorics, and graph theory.", Credits = 3, Schedule = "Mon/Wed 3:00-4:15 PM", InstructorName = "Dr. David Park", InstructorBio = "Specializes in combinatorics and theoretical computer science.", IsFeatured = false },
            // Physics
            new() { Id = 7, DepartmentId = 3, Title = "Physics I: Mechanics", Description = "Newtonian mechanics, energy, momentum, and rotational motion.", Credits = 4, Schedule = "Mon/Wed/Fri 9:00-9:50 AM", InstructorName = "Dr. Elena Rossi", InstructorBio = "Experimental physicist with research in particle physics at CERN.", IsFeatured = true },
            new() { Id = 8, DepartmentId = 3, Title = "Physics II: Electromagnetism", Description = "Electric and magnetic fields, circuits, and electromagnetic waves.", Credits = 4, Schedule = "Tue/Thu 9:30-10:45 AM", InstructorName = "Dr. Elena Rossi", InstructorBio = "Experimental physicist with research in particle physics at CERN.", IsFeatured = false },
            new() { Id = 9, DepartmentId = 3, Title = "Modern Physics", Description = "Relativity, quantum mechanics, and atomic structure.", Credits = 3, Schedule = "Mon/Wed 2:00-3:15 PM", InstructorName = "Dr. Frank Liu", InstructorBio = "Theoretical physicist researching quantum computing applications.", IsFeatured = false },
            // English
            new() { Id = 10, DepartmentId = 4, Title = "English Composition", Description = "Develop academic writing skills through essays and research papers.", Credits = 3, Schedule = "Tue/Thu 10:00-11:15 AM", InstructorName = "Prof. Grace Okafor", InstructorBio = "Award-winning author and writing instructor with 20 years of experience.", IsFeatured = false },
            new() { Id = 11, DepartmentId = 4, Title = "American Literature", Description = "Survey of major American literary works from colonial times to present.", Credits = 3, Schedule = "Mon/Wed 11:00 AM-12:15 PM", InstructorName = "Prof. Grace Okafor", InstructorBio = "Award-winning author and writing instructor with 20 years of experience.", IsFeatured = true },
            new() { Id = 12, DepartmentId = 4, Title = "Creative Writing", Description = "Workshop-based course exploring fiction, poetry, and creative nonfiction.", Credits = 3, Schedule = "Fri 1:00-3:45 PM", InstructorName = "Prof. Henry Walsh", InstructorBio = "Published novelist and poet, MFA from Iowa Writers' Workshop.", IsFeatured = false }
        };
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetCourses(string? search, int? departmentId)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue)
            query = query.Where(c => c.DepartmentId == departmentId.Value);

        if (!string.IsNullOrWhiteSpace(search))
            query = query.Where(c => c.Title.Contains(search, StringComparison.OrdinalIgnoreCase)
                || c.Description.Contains(search, StringComparison.OrdinalIgnoreCase));

        return query.ToList();
    }

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public bool SubmitEnrollmentRequest(EnrollmentRequest request) => true;
}

