@page "/courses"
@inject ICatalogService CatalogService

<PageTitle>Courses - University Course Catalog</PageTitle>

<h1>Courses</h1>

<form method="get" class="row g-3 mb-4">
    <div class="col-md-6">
        <input type="text" name="search" class="form-control" placeholder="Search courses..." value="@Search" />
    </div>
    <div class="col-md-4">
        <select name="departmentId" class="form-select">
            <option value="">All Departments</option>
            @foreach (var dept in CatalogService.GetDepartments())
            {
                <option value="@dept.Id" selected="@(DepartmentId == dept.Id)">@dept.Name</option>
            }
        </select>
    </div>
    <div class="col-md-2">
        <button type="submit" class="btn btn-primary w-100">Filter</button>
    </div>
</form>

@{
    var courses = CatalogService.GetCourses(Search, DepartmentId);
}

@if (courses.Any())
{
    <table class="table table-striped">
        <thead>
            <tr>
                <th>Title</th>
                <th>Department</th>
                <th>Credits</th>
                <th>Schedule</th>
                <th></th>
            </tr>
        </thead>
        <tbody>
            @foreach (var course in courses)
            {
                var dept = CatalogService.GetDepartment(course.DepartmentId);
                <tr>
                    <td>@course.Title</td>
                    <td>@dept?.Name</td>
                    <td>@course.Credits</td>
                    <td>@course.Schedule</td>
                    <td><a href="courses/@course.Id" class="btn btn-sm btn-outline-primary">Details</a></td>
                </tr>
            }
        </tbody>
    </table>
}
else
{
    <p class="text-muted">No courses found matching your criteria.</p>
}

@code {
    [SupplyParameterFromQuery]
    public string? Search { get; set; }

    [SupplyParameterFromQuery]
    public int? DepartmentId { get; set; }
}

@page "/courses/{Id:int}"
@inject ICatalogService CatalogService

@{
    var course = CatalogService.GetCourse(Id);
    var dept = course != null ? CatalogService.GetDepartment(course.DepartmentId) : null;
}

@if (course is null)
{
    <PageTitle>Course Not Found</PageTitle>
    <h1>Course Not Found</h1>
    <p>The requested course does not exist.</p>
    <a href="courses">Back to Courses</a>
}
else
{
    <PageTitle>@course.Title - University Course Catalog</PageTitle>

    <h1>@course.Title</h1>
    <p class="lead">@course.Description</p>

    <div class="row mt-4">
        <div class="col-md-6">
            <h4>Course Details</h4>
            <ul class="list-group mb-3">
                <li class="list-group-item"><strong>Department:</strong> @dept?.Name</li>
                <li class="list-group-item"><strong>Credits:</strong> @course.Credits</li>
                <li class="list-group-item"><strong>Schedule:</strong> @course.Schedule</li>
            </ul>
        </div>
        <div class="col-md-6">
            <h4>Instructor</h4>
            <p><strong>@course.InstructorName</strong></p>
            <p>@course.InstructorBio</p>
        </div>
    </div>

    <a href="enroll?courseId=@course.Id" class="btn btn-success mt-3">Enroll in This Course</a>
    <a href="courses" class="btn btn-outline-secondary mt-3 ms-2">Back to Courses</a>
}

@code {
    [Parameter]
    public int Id { get; set; }
}

@page "/enroll"
@inject ICatalogService CatalogService

<PageTitle>Enroll - University Course Catalog</PageTitle>

<h1>Course Enrollment</h1>

@if (_submitted)
{
    <div class="alert alert-success mt-3">
        <h4>Enrollment Submitted!</h4>
        <p>Thank you, <strong>@Model.Name</strong>. Your enrollment request for the selected course has been received.</p>
        <a href="courses" class="btn btn-primary">Browse More Courses</a>
    </div>
}
else
{
    <EditForm Model="Model" FormName="enrollment" method="post" Enhance OnValidSubmit="HandleSubmit">
        <DataAnnotationsValidator />
        <AntiforgeryToken />
        <ValidationSummary class="text-danger" />

        <div class="mb-3">
            <label for="studentName" class="form-label">Student Name</label>
            <InputText id="studentName" class="form-control" @bind-Value="Model.Name" />
            <ValidationMessage For="() => Model.Name" />
        </div>

        <div class="mb-3">
            <label for="studentId" class="form-label">Student ID</label>
            <InputText id="studentId" class="form-control" @bind-Value="Model.StudentId" />
            <ValidationMessage For="() => Model.StudentId" />
        </div>

        <div class="mb-3">
            <label for="courseId" class="form-label">Course</label>
            <InputSelect id="courseId" class="form-select" @bind-Value="Model.CourseId">
                <option value="0">-- Select a course --</option>
                @foreach (var course in CatalogService.GetCourses(null, null))
                {
                    <option value="@course.Id">@course.Title</option>
                }
            </InputSelect>
            <ValidationMessage For="() => Model.CourseId" />
        </div>

        <button type="submit" class="btn btn-primary">Submit Enrollment</button>
    </EditForm>
